/* @lc app=leetcode id=3515 lang=kotlin */ class Solution { fun ad(t: LongArray, i0: Int, v: Long) = generateSequence(i0) { it + (it and -it) }.takeWhile { it < t.size }.forEach { t[it] += v } fun qs(t: LongArray, i0: Int): Long = generateSequence(i0) { it - (it and -it) }.takeWhile { it > 0 }.sumOf { t[it] } fun treeQueries(n: Int, edges: Array<IntArray>, queries: Array<IntArray>): IntArray = edges.flatMap { (a, b, w) -> listOf(a to (b to w), b to (a to w)) }.groupBy({ it.first }, { it.second }).let { g -> IntArray(n + 1).let { par -> IntArray(n + 1).let { tin -> IntArray(n + 1).let { tout -> IntArray(n + 1).let { wt -> IntArray(1).let { ct -> java.util.ArrayDeque<Int>().also { it.addFirst(1) }.let { st -> generateSequence { st.pollFirst() }.forEach { e -> if (e > 0) ct.set(0, ct[0] + 1).also { tin[e] = ct[0] }.also { st.addFirst(-e) }.also { g[e].orEmpty().filter { (v, _) -> v != par[e] }.forEach { (v, w) -> par.set(v, e).also { wt[v] = w }.also { st.addFirst(v) } } } else tout.set(-e, ct[0]) }.let { LongArray(n + 3).let { t -> (2..n).forEach { v -> ad(t, tin[v], wt[v].toLong()).also { ad(t, tout[v] + 1, -wt[v].toLong()) } }.let { queries.mapNotNull { q -> if (q[0] == 1) (if (par[q[2]] == q[1]) q[2] else q[1]).let { c -> (q[3] - wt[c]).toLong().let { dl -> ad(t, tin[c], dl).also { ad(t, tout[c] + 1, -dl) }.also { wt[c] = q[3] }.let { null } } } else qs(t, tin[q[1]]).toInt() }.toIntArray() } } } } } } } } } } }